def test_show_accepts_v2(tmp_path, capsys):
    path = tmp_path / "config.json"
    path.write_text('{"version":2,"service":{"name":"demo","endpoint":{"host":"localhost","port":80}}}')
    assert main(["show", str(path)]) == 0
    assert json.loads(capsys.readouterr().out) == {"name": "demo", "address": "localhost:80", "enabled": True}

tests/test_migrate.py.text:
def test_migrate_writes_v2_and_returns_dict(tmp_path):
    path = tmp_path / "config.json"
    path.write_text(V1)
    result = migrate_file(str(path))
    assert result == {
        "version": 2,
        "service": {"name": "demo", "endpoint": {"host": "localhost", "port": 8080}},
        "enabled": True,
    }
    assert json.loads(path.read_text()) == result

def test_migrate_accepts_v2_input(tmp_path):
    path = tmp_path / "config.json"
    path.write_text('{"version":2,"service":{"name":"d","endpoint":{"host":"h","port":1}}}')
    assert migrate_file(str(path)) == {
        "version": 2,
        "service": {"name": "d", "endpoint": {"host": "h", "port": 1}},
        "enabled": True,
    }

tests/test_parser.py.text:
def test_enabled_defaults_to_true():
    assert loads('{"name":"demo","host":"localhost","port":8080}').enabled is True
    assert loads('{"version":2,"service":{"name":"d","endpoint":{"host":"h","port":1}}}').enabled is True

def test_unknown_fields_are_ignored():
    assert loads('{"name":"d","host":"h","port":1,"zzz":1}') == Config("d", "h", 1)
    assert loads('{"version":2,"service":{"name":"d","endpoint":{"host":"h","port":1},"extra":2},"other":{}}') == Config("d", "h", 1)

def test_error_shape(text, path, code):
    with pytest.raises(ConfigError) as info:
        loads(text)
    assert isinstance(info.value, ValueError)
    assert info.value.to_dict() == {"error": "invalid_config", "issues": [{"path": path, "code": code}]}

